,p_last_upd_yyyymmddhh24miss=>'20260928221654'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1034013192594846437)
,p_plug_name=>'Request KPIs'
,p_region_name=>'dashboard-kpis'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--styleB'
,p_component_template_options=>'#DEFAULT#:t-Cards--5cols:t-Cards--basic'
,p_plug_template=>wwv_flow_imp.id(1260710197212607767)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ''My Draft Requests'' card_label,',
'       to_char(count(*)) card_value,',
'       ''In preparation'' card_note',
'FROM adre_inv_item_request initre',
'WHERE initre.request_status = ''DRAFT''',
'UNION ALL',
'SELECT ''Pending Engineering'' card_label,',
'       to_char(count(DISTINCT initap.item_request_id)) card_value,',
'       ''Awaiting technical review'' card_note',
'FROM adre_inv_item_approval initap',
'WHERE initap.approval_type   = ''ENGINEERING''',
'AND   initap.approval_status = ''PENDING''',
'UNION ALL',
'SELECT ''Pending Finance'' card_label,',
'       to_char(count(DISTINCT initap.item_request_id)) card_value,',
'       ''Awaiting financial review'' card_note',
'FROM adre_inv_item_approval initap',
'WHERE initap.approval_type   = ''FINANCE''',
'AND   initap.approval_status = ''PENDING''',
'UNION ALL',
'SELECT ''Ready for EBS'' card_label,',
'       to_char(count(*)) card_value,',
'       ''Validation passed'' card_note',
'FROM adre_inv_item_request initre',
'WHERE initre.request_status = ''READY''',
'UNION ALL',
'SELECT ''Processed by EBS'' card_label,',
'       to_char(count(*)) card_value,',
'       ''Completed successfully'' card_note',
'FROM adre_inv_item_request initre',
'WHERE initre.request_status = ''PROCESSED'''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_prn_page_header=>'Request KPIs'
);
wwv_flow_imp_page.create_card(
 p_id=>wwv_flow_imp.id(1034013192594846725)
,p_region_id=>wwv_flow_imp.id(1034013192594846437)
,p_layout_type=>'GRID'
,p_title_adv_formatting=>false
,p_title_column_name=>'CARD_LABEL'
,p_sub_title_adv_formatting=>false
,p_sub_title_column_name=>'CARD_NOTE'
,p_body_adv_formatting=>false
,p_body_column_name=>'CARD_VALUE'
,p_second_body_adv_formatting=>false
,p_media_adv_formatting=>false
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1034013192594846444)
,p_plug_name=>'Recent Item Requests'
,p_region_name=>'recent-requests'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding'
,p_plug_template=>wwv_flow_imp.id(1260710197212607767)
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT initre.item_request_id,',
'       initre.item_number,',
'       itetyp.item_type_name,',
'       CASE',
'         WHEN EXISTS (',
'                SELECT 1',
'                FROM adre_inv_item_approval initap',
'                WHERE initap.item_request_id  = initre.item_request_id',
'                AND   initap.approval_type     = ''ENGINEERING''',
'                AND   initap.approval_status   = ''PENDING''',
'              ) THEN ''Engineering Pending''',
'         WHEN EXISTS (',
'                SELECT 1',
'                FROM adre_inv_item_approval initap',
'                WHERE initap.item_request_id  = initre.item_request_id',
'                AND   initap.approval_type     = ''FINANCE''',
'                AND   initap.approval_status   = ''PENDING''',
'              ) THEN ''Finance Pending''',
'         WHEN initre.request_status IN (''PROCESSED'', ''COMPLETED'') THEN ''Processed''',
'         WHEN initre.request_status = ''READY'' THEN ''Ready for EBS''',
'         WHEN initre.request_status = ''DRAFT'' THEN ''Draft''',
'         WHEN initre.request_status = ''ERROR'' THEN ''Error''',
'         ELSE initre.request_status',
'       END request_status,',
'       CASE',
'         WHEN initre.request_status = ''DRAFT'' THEN ''Data Entry''',
'         WHEN initre.request_status = ''READY'' THEN ''EBS''',
'         WHEN initre.request_status IN (''PROCESSING'', ''ERROR'') THEN ''EBS''',
'         WHEN initre.request_status IN (''PROCESSED'', ''COMPLETED'') THEN ''Complete''',
'         WHEN EXISTS (',
'                SELECT 1',
'                FROM adre_inv_item_approval initap',
'                WHERE initap.item_request_id  = initre.item_request_id',
'                AND   initap.approval_type     = ''ENGINEERING''',
'                AND   initap.approval_status   = ''PENDING''',
'              ) THEN ''Engineering''',
'         WHEN EXISTS (',
'                SELECT 1',
'                FROM adre_inv_item_approval initap',
'                WHERE initap.item_request_id  = initre.item_request_id',
'                AND   initap.approval_type     = ''FINANCE''',
'                AND   initap.approval_status   = ''PENDING''',
'              ) THEN ''Finance''',
'         ELSE ''Review''',
'       END current_step,',
'       initre.last_update_date,',
'       initiator initiator',
'FROM adre_inv_item_request initre,',
'     adre_inv_item_type itetyp',
'WHERE itetyp.item_type_id = initre.item_type_id',
'ORDER BY initre.last_update_date DESC'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Recent Item Requests'
);
