,p_plug_name=>'All Requests'
,p_region_name=>'all-requests-report'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding'
,p_plug_template=>wwv_flow_imp.id(1260710197212607767)
,p_plug_display_sequence=>28
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT initre.item_request_id,',
'       initre.item_number,',
'       itetyp.item_type_name,',
'       initre.initiator,',
'       CASE',
'         WHEN EXISTS (',
'                SELECT 1',
'                FROM adre_inv_item_approval initap',
'                WHERE initap.item_request_id = initre.item_request_id',
'                AND   initap.approval_type    = ''ENGINEERING''',
'                AND   initap.approval_status  = ''APPROVED''',
'              ) THEN ''Approved''',
'         WHEN EXISTS (',
'                SELECT 1',
'                FROM adre_inv_item_approval initap',
'                WHERE initap.item_request_id = initre.item_request_id',
'                AND   initap.approval_type    = ''ENGINEERING''',
'                AND   initap.approval_status  = ''PENDING''',
'              ) THEN ''Pending''',
'         WHEN EXISTS (',
'                SELECT 1',
'                FROM adre_inv_item_approval initap',
'                WHERE initap.item_request_id = initre.item_request_id',
'                AND   initap.approval_type    = ''ENGINEERING''',
'                AND   initap.approval_status  IN (''REJECTED'', ''CHANGES_REQUESTED'')',
'              ) THEN ''Needs Attention''',
'         ELSE ''Not Started''',
'       END engineering_status,',
'       :p10_item_type_id hh,',
'       CASE',
'         WHEN EXISTS (',
'                SELECT 1',
'                FROM adre_inv_item_approval initap',
'                WHERE initap.item_request_id = initre.item_request_id',
'                AND   initap.approval_type    = ''FINANCE''',
'                AND   initap.approval_status  = ''APPROVED''',
'              ) THEN ''Approved''',
'         WHEN EXISTS (',
'                SELECT 1',
'                FROM adre_inv_item_approval initap',
'                WHERE initap.item_request_id = initre.item_request_id',
'                AND   initap.approval_type    = ''FINANCE''',
'                AND   initap.approval_status  = ''PENDING''',
'              ) THEN ''Pending''',
'         WHEN EXISTS (',
'                SELECT 1',
'                FROM adre_inv_item_approval initap',
'                WHERE initap.item_request_id = initre.item_request_id',
'                AND   initap.approval_type    = ''FINANCE''',
'                AND   initap.approval_status  IN (''REJECTED'', ''CHANGES_REQUESTED'')',
'              ) THEN ''Needs Attention''',
'         ELSE ''Not Started''',
'       END finance_status,',
'       CASE initre.request_status',
'         WHEN ''READY''      THEN ''Ready''',
'         WHEN ''PROCESSING'' THEN ''Processing''',
'         WHEN ''PROCESSED''  THEN ''Processed''',
'         WHEN ''COMPLETED''  THEN ''Processed''',
'         WHEN ''ERROR''      THEN ''Error''',
'         ELSE ''In Progress''',
'       END ebs_status,',
'       initre.last_update_date',
'FROM adre_inv_item_request initre,',
'     adre_inv_item_type itetyp',
'WHERE itetyp.item_type_id = initre.item_type_id',
'AND   (:p10_item_number IS NULL',
'OR     upper(initre.item_number) LIKE ''%'' || upper(:p10_item_number) || ''%'')',
'AND   (:p10_item_type_id IS NULL',
'OR     initre.item_type_id = :p10_item_type_id)',
'AND   (:p10_request_status IS NULL',
'OR     initre.request_status = :p10_request_status)',
'ORDER BY initre.item_request_id DESC'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P10_ITEM_NUMBER,P10_ITEM_TYPE_ID,P10_REQUEST_STATUS'
,p_prn_page_header=>'All Requests'
);
