,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT itebom.item_bom_id,',
'       reqorg.organization_role,',
'       itebom.alternate_bom_designator,',
'       itebom.bom_description,',
'       itebom.effectivity_date,',
'       itebom.bom_status,',
'       count(bomcom.item_bom_comp_id) component_count,',
'       itebom.api_return_status',
'FROM adre_inv_item_bom itebom,',
'     adre_inv_item_request_org reqorg,',
'     adre_inv_item_bom_comp bomcom',
'WHERE reqorg.request_org_id = itebom.request_org_id',
'AND   reqorg.item_request_id = :p20_item_request_id',
'AND   bomcom.item_bom_id(+)   = itebom.item_bom_id',
'GROUP BY itebom.item_bom_id,',
'         reqorg.organization_role,',
'         itebom.alternate_bom_designator,',
'         itebom.bom_description,',
'         itebom.effectivity_date,',
'         itebom.bom_status,',
'         itebom.api_return_status',
'ORDER BY itebom.item_bom_id'))
,p_plug_source_type=>'NATIVE_IR'
