,p_plug_display_sequence=>70
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT initre.item_request_id,',
'       initre.item_number,',
'       itetyp.item_type_name,',
'       initre.request_status,',
'       (',
'         SELECT count(*)',
'         FROM adre_inv_item_request_org reqorg',
'         WHERE reqorg.item_request_id = initre.item_request_id',
'       ) organization_count,',
'       (',
'         SELECT count(*)',
'         FROM adre_inv_item_category itecat,',
'              adre_inv_item_request_org reqorg',
'         WHERE reqorg.item_request_id = initre.item_request_id',
'         AND   itecat.request_org_id   = reqorg.request_org_id',
'       ) category_count,',
'       (',
'         SELECT count(*)',
'         FROM adre_inv_item_approval initap',
'         WHERE initap.item_request_id = initre.item_request_id',
'         AND   initap.approval_status = ''APPROVED''',
'       ) approved_stages,',
'       initre.api_return_status',
'FROM adre_inv_item_request initre,',
'     adre_inv_item_type itetyp',
'WHERE initre.item_request_id = :p20_item_request_id',
'AND   itetyp.item_type_id    = initre.item_type_id'))
