wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1034013192594846741)
,p_plug_name=>'Request Workflow'
,p_region_name=>'request-workflow'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--styleB'
,p_component_template_options=>'#DEFAULT#:t-Cards--4cols:t-Cards--basic'
,p_plug_template=>wwv_flow_imp.id(1260710197212607767)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ''Data Entry'' step_label,',
'       CASE',
'         WHEN initre.request_status = ''DRAFT'' THEN ''In Progress''',
'         ELSE ''Complete''',
'       END step_status',
'FROM adre_inv_item_request initre',
'WHERE initre.item_request_id = :p20_item_request_id',
'',
'UNION ALL',
'',
'SELECT ''Engineering'',',
'       CASE',
'         WHEN EXISTS (',
'                SELECT 1',
'                FROM adre_inv_item_approval initap',
'                WHERE initap.item_request_id = initre.item_request_id',
'                AND   initap.approval_type    = ''ENGINEERING''',
'                AND   initap.approval_status  = ''APPROVED''',
'              ) THEN ''Approved''',
'         WHEN EXISTS (',
'                SELECT 1',
'                FROM adre_inv_item_approval initap',
'                WHERE initap.item_request_id = initre.item_request_id',
'                AND   initap.approval_type    = ''ENGINEERING''',
'                AND   initap.approval_status  = ''PENDING''',
'              ) THEN ''Pending''',
'         WHEN EXISTS (',
'                SELECT 1',
'                FROM adre_inv_item_approval initap',
'                WHERE initap.item_request_id = initre.item_request_id',
'                AND   initap.approval_type    = ''ENGINEERING''',
'                AND   initap.approval_status  IN (''REJECTED'', ''CHANGES_REQUESTED'')',
'              ) THEN ''Needs Attention''',
'         ELSE ''Not Started''',
'       END',
'FROM adre_inv_item_request initre',
'WHERE initre.item_request_id = :p20_item_request_id',
'',
'UNION ALL',
'',
'SELECT ''Finance'',',
'       CASE',
'         WHEN EXISTS (',
'                SELECT 1',
'                FROM adre_inv_item_approval initap',
'                WHERE initap.item_request_id = initre.item_request_id',
'                AND   initap.approval_type    = ''FINANCE''',
'                AND   initap.approval_status  = ''APPROVED''',
'              ) THEN ''Approved''',
'         WHEN EXISTS (',
'                SELECT 1',
'                FROM adre_inv_item_approval initap',
'                WHERE initap.item_request_id = initre.item_request_id',
'                AND   initap.approval_type    = ''FINANCE''',
'                AND   initap.approval_status  = ''PENDING''',
'              ) THEN ''Pending''',
'         WHEN EXISTS (',
'                SELECT 1',
'                FROM adre_inv_item_approval initap',
'                WHERE initap.item_request_id = initre.item_request_id',
'                AND   initap.approval_type    = ''FINANCE''',
'                AND   initap.approval_status  IN (''REJECTED'', ''CHANGES_REQUESTED'')',
'              ) THEN ''Needs Attention''',
'         ELSE ''Not Started''',
'       END',
'FROM adre_inv_item_request initre',
'WHERE initre.item_request_id = :p20_item_request_id',
'',
'UNION ALL',
'',
'SELECT ''EBS'',',
'       CASE initre.request_status',
'         WHEN ''READY''      THEN ''Ready''',
'         WHEN ''PROCESSING'' THEN ''Processing''',
'         WHEN ''PROCESSED''  THEN ''Complete''',
'         WHEN ''COMPLETED''  THEN ''Complete''',
'         WHEN ''ERROR''      THEN ''Error''',
'         ELSE ''Not Ready''',
'       END',
'FROM adre_inv_item_request initre',
'WHERE initre.item_request_id = :p20_item_request_id'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P20_ITEM_REQUEST_ID'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_plug_display_condition_type=>'ITEM_IS_NOT_NULL'
,p_plug_display_when_condition=>'P20_ITEM_REQUEST_ID'
);
