,p_last_upd_yyyymmddhh24miss=>'20260928223305'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1034013192594846559)
,p_plug_name=>'Engineering Queue'
,p_region_name=>'engineering-queue'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding'
,p_plug_template=>wwv_flow_imp.id(1260710197212607767)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT initap.item_approval_id,',
'       initap.item_request_id,',
'       initre.request_number,',
'       initre.item_number,',
'       itetyp.item_type_name,',
'       initap.approval_type,',
'       CASE initap.approval_status',
'         WHEN ''PENDING''           THEN ''Pending''',
'         WHEN ''APPROVED''          THEN ''Approved''',
'         WHEN ''REJECTED''          THEN ''Rejected''',
'         WHEN ''CHANGES_REQUESTED'' THEN ''Changes Requested''',
'         ELSE initap.approval_status',
'       END approval_status,',
'       initap.assigned_to,',
'       initap.decision_by,',
'       initap.decision_date,',
'       initap.decision_comments',
'FROM adre_inv_item_approval initap,',
'     adre_inv_item_request initre,',
'     adre_inv_item_type itetyp',
'WHERE initap.item_request_id = initre.item_request_id',
'AND   itetyp.item_type_id    = initre.item_type_id',
'AND   initap.approval_type   = ''ENGINEERING''',
'ORDER BY CASE initap.approval_status',
'           WHEN ''PENDING'' THEN 1',
'           ELSE 2',
'         END,',
'         initre.item_request_id DESC'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Engineering Queue'
);
