'       CASE initap.approval_status',
'         WHEN ''PENDING''           THEN ''Pending''',
'         WHEN ''APPROVED''          THEN ''Approved''',
'         WHEN ''REJECTED''          THEN ''Rejected''',
'         WHEN ''CHANGES_REQUESTED'' THEN ''Changes Requested''',
'         ELSE initap.approval_status',
