,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT initre.item_request_id,',
'       initre.request_number,',
'       initre.item_number,',
'       itetyp.item_type_name,',
'       initre.primary_uom_code,',
'       CASE initre.request_status',
'         WHEN ''READY''      THEN ''Ready for EBS''',
'         WHEN ''PROCESSING'' THEN ''Processing''',
'         ELSE initre.request_status',
'       END request_status,',
'       initre.ebs_submit_date,',
'       (',
'         SELECT count(*)',
'         FROM adre_inv_item_approval initap',
'         WHERE initap.item_request_id = initre.item_request_id',
'         AND   initap.approval_status = ''APPROVED''',
'       ) approved_stages',
'FROM adre_inv_item_request initre,',
'     adre_inv_item_type itetyp',
'WHERE itetyp.item_type_id  = initre.item_type_id',
'AND   initre.request_status IN (''READY'', ''PROCESSING'')',
'ORDER BY initre.item_request_id DESC'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Ready for EBS'
);
